import{_ as t,c as a,a2 as o,o as s}from"./chunks/framework.CoXjB5sU.js";const r="/assets/CreateDetailsPath.CXNFw-84.png",n="/assets/CreateNavigationTreeRefresh.BNLnyIB4.png",i="/assets/CreateItemDetailsCreateProject.Ccl0_dwb.png",l="/assets/WebUploadForm.BSpc9JlT.png",c="/assets/WebUploadForm2.DlblGhS8.png",p="data:image/png;base64,",h="/assets/WebUploadForm4.bquAlzwm.png",d="/assets/AssetUploadForm.DEv1AK0V.png",u="/assets/AssetUploadResult.Cwak0qMr.png",C=JSON.parse('{"title":"Upload content using the web interface","description":"","frontmatter":{},"headers":[],"relativePath":"doc/guides/usage/uploading-content-to-create/using-web-interface.md","filePath":"doc/guides/usage/uploading-content-to-create/using-web-interface.md"}'),m={name:"doc/guides/usage/uploading-content-to-create/using-web-interface.md"};function g(f,e,w,b,A,k){return s(),a("div",null,e[0]||(e[0]=[o('<h1 id="upload-content-using-the-web-interface" tabindex="-1">Upload content using the web interface <a class="header-anchor" href="#upload-content-using-the-web-interface" aria-label="Permalink to &quot;Upload content using the web interface&quot;">​</a></h1><p>The Create module web interface lets you upload calculations and assets into your workspace directly from the browser. If you prefer working from a terminal, read the <a href="./using-shell-client.html">Using the shell client</a> page instead.</p><h2 id="paths" tabindex="-1">Paths <a class="header-anchor" href="#paths" aria-label="Permalink to &quot;Paths&quot;">​</a></h2><p>Any element within the Create module has an associated path that defines its location in the workspace hierarchy. You can check it at the top of the <strong>Item Details</strong> form:</p><p><img src="'+r+'" alt="Element current path"></p><p>Paths work the same way as standard operating system folder paths, so you can navigate them up and down. All paths start with a fixed string containing your username: <strong>/db/username</strong>. This is the <strong>root</strong> of your path, and you can create the projects you need from here.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>Calculations are not allowed</strong> in the <strong>root path</strong> directly; they must be held inside a project.</p></div><h2 id="creating-a-project" tabindex="-1">Creating a project <a class="header-anchor" href="#creating-a-project" aria-label="Permalink to &quot;Creating a project&quot;">​</a></h2><p>Projects created in the root path are called <em>root projects</em>. To create one:</p><ol><li><p>Clear the current path by clicking the <strong>Refresh</strong> button on top of the <em>My workspace</em> tab; the path returns to the root.</p><p><img src="'+n+'" alt="Refresh and reset path button"></p></li><li><p>Fill in the project details in the <em>Item Details</em> frame. <strong>Name</strong> and <strong>description</strong> are mandatory.</p><p><img src="'+i+'" alt="Create project form, check root path on top"></p></li><li><p>Click <strong>Create Project</strong>. The workspace tree refreshes and your project appears in the hierarchy.</p></li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>No symbol characters can be used in the project name, as they are not allowed in directory names inside current operating systems.</p></div><p>To create subprojects inside an existing project, click on that project, replace the name and description in the <em>Item Details</em> frame and click <strong>Create Project</strong> again; the new project is generated inside the selected parent project.</p><h2 id="calculation-upload" tabindex="-1">Calculation upload <a class="header-anchor" href="#calculation-upload" aria-label="Permalink to &quot;Calculation upload&quot;">​</a></h2><p>To upload a calculation you first have to select the project that will contain it. The upper right panel then displays the <strong>Calculation upload</strong> tab with the upload form:</p><ol><li><p>Fill in the calculation <strong>Name</strong> and <strong>Description</strong>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The <em>Name</em> field must not contain blank spaces or special characters like \\*@[]; otherwise it will be normalized to underscore symbols.</p></div></li><li><p>Select the <strong>Type</strong> of the calculation (the software package that generated it). The form adapts and displays one upload row per expected file: <em>Input file</em>, <em>Output file</em>, <em>Additional file</em>, etc.</p><p><img src="'+l+'" alt="Calculation upload form with type selection"></p></li><li><p>Attach each file using the upload button of its row. Rows that accept multiple files (like <em>Additional file</em>) open a dialog where you can pick several files at once.</p><p><img src="'+c+'" alt="Calculation files attached"></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you upload multiple files with the same name, the Create module renames them with a numeric code: two <em>geometry.txt</em> files become <em>geometry.txt</em> and <em>geometry_2.txt</em>.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Some calculation types require uploading files in a certain order or appending specific files to work properly. Please refer to the <a href="./using-shell-client/shell-automated-scripts.html">shell automated scripts</a> section for an extended description of each type.</p></div></li><li><p>Click <strong>Load Calculation</strong>. The form resets and a progress meter appears at the bottom right corner of the window, showing the queue of conversions.</p><p><img src="'+p+'" alt="Upload progress meter"></p><p>Bear in mind that converting and digesting big files can take a while. The progress meter also reports errors during upload; click the warning icon to display a longer explanation about the failure (please keep it and send it to us if that happens).</p></li><li><p>Once the conversion finishes, the calculation appears inside the project in the workspace tree.</p><p><img src="'+h+'" alt="Uploaded calculation inside the project"></p></li></ol><h2 id="asset-upload" tabindex="-1">Asset upload <a class="header-anchor" href="#asset-upload" aria-label="Permalink to &quot;Asset upload&quot;">​</a></h2><p>Assets are complementary files attached to a project, such as reference papers, RMMD documents or JSON data sets. They are stored next to the project calculations and can be published together with them.</p><p>To upload an asset:</p><ol><li><p>Right click on the destination project in the workspace tree and choose <strong>New asset...</strong>. The <strong>Asset upload</strong> tab opens in the upper right panel.</p></li><li><p>Select the asset <strong>Type</strong>: <em>Project documents</em>, <em>RMMD</em> or <em>JSON data</em>.</p></li><li><p>Fill in the asset <strong>Name</strong> and <strong>Description</strong>.</p></li><li><p>Optionally, link the asset to specific calculations of the project; by default assets relate to the whole project.</p></li><li><p>Attach the asset files using the <strong>Add files...</strong> button.</p><p><img src="'+d+'" alt="Asset upload form with an attached document"></p></li><li><p>Click <strong>Load Asset</strong>. The asset is added to the project and displayed in the workspace tree with the <em>AST</em> type code.</p><p><img src="'+u+'" alt="Asset and calculations inside the project"></p></li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Assets support any file format, so they are the right place for manuscript drafts, supporting documents or raw data sets that do not fit the calculation conversion workflow.</p></div>',20)]))}const j=t(m,[["render",g]]);export{C as __pageData,j as default};
